<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, type CSSProperties } from 'vue'
import DialogFrame from '../../ui/DialogFrame.vue'
import TableIcon from '../../components/TableIcon.vue'
import {useDragReorder} from '../../ui/useDragReorder'
import type { ViewSnapshot, ViewsPanelRuntime } from './runtime'

const props=withDefaults(defineProps<{runtime:ViewsPanelRuntime;snapshot:()=>ViewSnapshot;modified?:boolean;pending?:boolean}>(),{modified:false,pending:false})
const emit=defineEmits<{notice:[message:string];requireApply:[];committed:[]}>()
const opened=ref(false),root=ref<HTMLElement>(),trigger=ref<HTMLElement>(),popup=ref<HTMLElement>(),popupStyle=ref<CSSProperties>({}),error=ref(''),busy=ref(false)
const editor=ref<{id?:string;name:string}>(),confirmation=ref<{kind:'update'|'delete';id:string;name:string}>()
const views=computed(()=>props.runtime.views.value),current=computed(()=>props.runtime.current.value)
const editable=computed(()=>!!current.value&&!current.value.isSystem&&!current.value.isReadOnly)
function position(){
  if(!opened.value||!trigger.value||!popup.value)return
  const anchor=trigger.value.getBoundingClientRect(),box=popup.value.getBoundingClientRect()
  const width=document.documentElement.clientWidth||window.innerWidth,height=document.documentElement.clientHeight||window.innerHeight
  popupStyle.value={maxWidth:`${Math.max(0,width-16)}px`,maxHeight:`${Math.max(0,height-16)}px`,left:`${Math.max(8,Math.min(anchor.left,width-Math.min(box.width,width-16)-8))}px`,top:`${Math.max(8,Math.min(anchor.bottom+8,height-box.height-8))}px`}
}
async function toggle(){opened.value=!opened.value;error.value='';await nextTick();position()}
async function run(action:()=>void|Promise<unknown>,message?:string){if(busy.value)return;busy.value=true;error.value='';try{await action();if(message)emit('notice',message);return true}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，请重试。';return false}finally{busy.value=false}}
async function apply(id:string){if(await run(()=>props.runtime.apply(id))){opened.value=false;emit('notice',`已切换到“${current.value?.name}”。`)}}
function requireApplied(){if(!props.pending)return true;opened.value=false;emit('requireApply');emit('notice','查询条件还未应用，请先点击查询，再保存视图。');return false}
function nameView(id?:string){if(!id&&!requireApplied())return;const view=views.value.find(item=>item.id===id);editor.value={...(id?{id}:{}),name:view?.name??''};opened.value=false;error.value=''}
async function saveName(){const value=editor.value;if(!value)return;if(await run(()=>value.id?props.runtime.rename(value.id,value.name):props.runtime.saveAs(value.name,props.snapshot()),'视图已保存。')){editor.value=undefined;if(!value.id)emit('committed')}}
function confirm(kind:'update'|'delete',id:string){if(kind==='update'&&!requireApplied())return;const view=views.value.find(item=>item.id===id);if(!view)return;confirmation.value={kind,id,name:view.name};opened.value=false;error.value=''}
async function confirmAction(){const value=confirmation.value;if(!value)return;if(await run(()=>value.kind==='delete'?props.runtime.remove(value.id):props.runtime.update(value.id,props.snapshot()),value.kind==='delete'?'视图已删除。':'视图设置已更新。')){confirmation.value=undefined;if(value.kind==='update')emit('committed')}}
function canMove(index:number,offset:number){const target=index+offset;return target>=0&&target<views.value.length&&!views.value[index]?.isSystem&&!views.value.slice(Math.min(index,target),Math.max(index,target)+1).some(view=>view.isSystem)}
async function move(id:string,offset:number){await run(()=>props.runtime.move(id,offset))}
const reorder=useDragReorder({ids:()=>views.value.map(view=>view.id),disabled:()=>busy.value,canMove:id=>!views.value.find(view=>view.id===id)?.isSystem,canDrop:(id,target)=>{const from=views.value.findIndex(view=>view.id===id);return canMove(from,views.value.findIndex(view=>view.id===target)-from)},move:(id,target)=>{void move(id,views.value.findIndex(view=>view.id===target)-views.value.findIndex(view=>view.id===id))}})
function outside(event:PointerEvent){if(event.target instanceof Node&&!root.value?.contains(event.target))opened.value=false}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&opened.value){event.preventDefault();event.stopPropagation();opened.value=false;trigger.value?.focus()}}
onMounted(()=>{document.addEventListener('pointerdown',outside);window.addEventListener('resize',position)})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside);window.removeEventListener('resize',position)})
</script>
<template>
  <div ref="root" class="bt-views" @keydown="escape">
    <button ref="trigger" class="bt-views-trigger" type="button" aria-label="保存与切换视图" aria-haspopup="dialog" :aria-expanded="opened" @click="toggle"><TableIcon name="bookmark" :size="13"/><span>{{current?.name??'全部'}}</span><TableIcon name="chevron-down" :size="13"/></button>
    <div v-if="opened" ref="popup" class="bt-views-popup" role="dialog" aria-label="我的视图" :style="popupStyle">
      <header><h3>我的视图</h3><span>{{views.length}} / 50</span></header><p class="bt-views-hint">保存查询和表格设置；标为默认后，重新打开时自动应用。</p>
      <div class="bt-views-list"><div v-for="(view,index) in views" :key="view.id" class="bt-view-row" :class="{'is-current':runtime.activeId.value===view.id}" v-bind="reorder.row(view.id)">
        <button class="bt-view-icon" :disabled="view.isSystem||busy" v-bind="reorder.handle(view.id)" aria-label="拖动视图排序"><TableIcon name="grip" :size="12"/></button>
        <button class="bt-view-name" @click="apply(view.id)"><span :title="view.name">{{view.name}}</span><small v-if="view.isDefault">默认</small></button>
        <div class="bt-view-tools"><button class="bt-view-icon" :class="{'is-active':view.isDefault}" :title="`设为默认 ${view.name}`" :aria-pressed="view.isDefault===true" :disabled="busy" @click="run(()=>runtime.setDefault(view.id),'重新打开页面时将使用此视图。')"><TableIcon name="star" :size="12"/></button><button class="bt-view-icon" :title="`重命名 ${view.name}`" :disabled="view.isSystem||view.isReadOnly||busy" @click="nameView(view.id)"><TableIcon name="edit" :size="12"/></button><button class="bt-view-icon bt-view-move" :title="`上移 ${view.name}`" :disabled="!canMove(index,-1)||busy" @click="move(view.id,-1)"><TableIcon name="chevron-up" :size="12"/></button><button class="bt-view-icon bt-view-move" :title="`下移 ${view.name}`" :disabled="!canMove(index,1)||busy" @click="move(view.id,1)"><TableIcon name="chevron-down" :size="13"/></button><button class="bt-view-icon" :title="`删除 ${view.name}`" :disabled="view.isSystem||view.isReadOnly||busy" @click="confirm('delete',view.id)"><TableIcon name="trash" :size="12"/></button></div>
      </div></div><p v-if="error" role="alert" class="bt-ui-error">{{error}}</p>
      <footer><button class="bt-ui-button text" :disabled="!editable||!modified||busy" @click="current&&confirm('update',current.id)">更新当前视图</button><button class="bt-ui-button primary" :disabled="views.length>=50||busy" @click="nameView()"><TableIcon name="plus" :size="14"/>另存为视图</button></footer>
    </div>
  </div>
  <DialogFrame v-if="editor" class="bt-view-name-dialog" :title="editor.id?'重命名视图':'保存视图'" :subtitle="editor.id?'修改名称，不改变已保存的条件。':'保存当前查询、列样式、排序规则、操作按钮和表格外观。'" :busy="busy" @close="editor=undefined"><form id="bt-view-name-form" novalidate @submit.prevent="saveName"><label class="bt-ui-field"><span>视图名称 <b class="bt-view-required">*</b></span><input v-model="editor.name" autofocus maxlength="30" autocomplete="off" placeholder="例如：华东待评审报价"/><small>最多 30 个字符，不能与已有视图重名。</small></label><p v-if="error" role="alert" class="bt-ui-error">{{error}}</p></form><template #footer><button class="bt-ui-button" :disabled="busy" @click="editor=undefined">取消</button><button class="bt-ui-button primary" :disabled="busy" form="bt-view-name-form" type="submit">保存</button></template></DialogFrame>
  <DialogFrame v-if="confirmation" class="bt-view-name-dialog" :title="confirmation.kind==='delete'?'删除视图':'更新视图'" :busy="busy" @close="confirmation=undefined"><p class="bt-view-confirm">{{confirmation.kind==='delete'?`确认删除“${confirmation.name}”？只删除视图设置，不会删除报价数据。`:`将当前查询、排序和表格设置保存到“${confirmation.name}”？`}}</p><p v-if="error" role="alert" class="bt-ui-error">{{error}}</p><template #footer><button class="bt-ui-button" :disabled="busy" @click="confirmation=undefined">取消</button><button class="bt-ui-button" :class="confirmation.kind==='delete'?'danger':'primary'" :disabled="busy" @click="confirmAction">{{confirmation.kind==='delete'?'删除视图':'更新视图'}}</button></template></DialogFrame>
</template>
<style>
.bt-views{position:relative;min-width:0}.bt-views .bt-views-trigger{height:32px;color:#2468e8;background:#f2f6fe;border:1px solid #e3ecfc;border-radius:5px;display:flex;align-items:center;gap:6px;padding:0 8px;min-width:0;font:inherit;line-height:normal;cursor:pointer}.bt-views .bt-views-trigger:hover,.bt-views .bt-views-trigger[aria-expanded="true"]{background:#edf4ff;color:#2468e8}.bt-views-trigger>span{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.bt-views-popup{display:flex;flex-direction:column;overflow:hidden;line-height:normal;position:fixed;z-index:80;width:438px;max-width:calc(100vw - 16px);background:#fff;border:1px solid #dde5f0;border-radius:8px;box-shadow:0 12px 34px #283d5b20,0 2px 7px #283d5b06;color:#526681;font-size:13px;animation:bt-views-in .16s ease-out}.bt-views-popup>header{flex-shrink:0;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e2e7ee}.bt-views-popup h3{margin:0;font-size:14px;font-weight:600;color:#293e5a}.bt-views-popup header>span{font-size:12px;color:#92a0b3}.bt-views-hint{flex-shrink:0;margin:0;padding:10px 16px 0;font-size:11px;color:#99a3b3;line-height:1.6}.bt-views-list{min-height:0;max-height:380px;overflow:auto;padding:7px}.bt-view-row{display:flex;align-items:center;gap:4px;padding:4px;border-radius:5px;border:1px solid transparent}.bt-view-row:hover{background:#f8faff}.bt-view-row.is-current{background:#f0f5ff}.bt-views .bt-view-icon{min-height:26px;display:inline-flex;align-items:center;justify-content:center;width:23px;height:26px;border:0;border-radius:4px;background:transparent;color:#76869b;cursor:pointer;padding:0}.bt-views .bt-view-icon:hover,.bt-views .bt-view-icon.is-active{color:#2468e8;background:#edf4ff}.bt-views .bt-view-icon:disabled{opacity:.35;cursor:not-allowed}.bt-views .bt-view-name{min-height:0;justify-content:flex-start;line-height:normal;display:flex;gap:7px;align-items:center;flex:1;min-width:0;text-align:left;border:0;background:none;padding:7px 0;color:#596c86;font-size:12px;cursor:pointer}.bt-view-name>span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.bt-views .bt-view-row.is-current .bt-view-name{color:#2468e8}.bt-view-name small{color:#8996aa;background:#eaf0f7;padding:1px 4px;font-size:10px;flex-shrink:0;border-radius:3px}.bt-view-tools{display:flex}.bt-views-popup>footer{flex-shrink:0;display:flex;justify-content:space-between;gap:10px;padding:11px 14px;border-top:1px solid #e2e7ee;background:#fcfdff}.bt-views-popup button:disabled{cursor:not-allowed;opacity:.4}.bt-views-popup .bt-ui-button{font-size:12px;min-height:30px;height:30px}.bt-view-name-dialog{line-height:normal;width:min(480px,calc(100vw - 32px))}.bt-view-name-dialog .bt-dialog-header{padding:16px 24px;align-items:flex-start}.bt-view-name-dialog .bt-dialog-header h2{font-size:16px;line-height:24px}.bt-view-name-dialog .bt-dialog-header p{line-height:18px;color:#64748b}.bt-view-name-dialog .bt-dialog-body{padding:20px 24px}.bt-view-name-dialog .bt-dialog-footer{padding:12px 24px}.bt-view-required{color:#db5a62;font-weight:400}.bt-view-confirm{font-size:13px;line-height:1.8;color:#526681;margin:4px 0}@keyframes bt-views-in{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}@media(max-width:760px){.bt-views-trigger>span{max-width:160px}.bt-views-list{min-height:0;max-height:300px}}@media(max-width:380px){.bt-view-move{display:none}}@media(prefers-reduced-motion:reduce){.bt-views-popup{animation:none}}
</style>
